162	        return { error: "第 " + (i + 1) + " 个开放时段未填写完整，请补全或删除该时段。" };
163	      }
164	      hours.push({ weekday: weekday, start: start, end: end });
165	    }
166	    return { hours: hours };
167	  }
168	
169	  function toMinutes(hhmm) {
170	    var parts = hhmm.split(":");
171	    return parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);
172	  }
173	
174	  function escapeHTML(value) {
175	    return String(value).replace(/[&<>"']/g, function (c) {
176	      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
177	    });
178	  }
179	
180	  // canonicalDigits 按十进制原文校验容量输入：只接受由数字组成的正整数，
181	  // 返回去掉前导零后的数字原文；为空、为零或包含负号、小数点等内容时返回
182	  // null。全程不经过 Number/parseInt，否则 9007199254740993 这样超过
183	  // Number.MAX_SAFE_INTEGER 的值会被悄悄舍入成相邻整数。
184	  function canonicalDigits(raw) {
185	    if (!/^\d+$/.test(raw)) return null;
186	    var digits = raw.replace(/^0+/, "");
187	    if (digits === "") return null; // 全是 0：容量为零，不接受
188	    return digits;
189	  }
190	
191	  // buildVenueRequestBody 直接拼接 JSON 文本，让容量以输入的十进制数字原文
192	  // 发送：不能用 JSON.stringify({capacity: 数字})，大整数在转成 Number 时
193	  // 已经被舍入，stringify 只会写回错误的值。名称、时区是字符串，交给
194	  // JSON.stringify 转义；传输报文中 capacity 仍是 JSON 数字。
195	  function buildVenueRequestBody(name, capacityDigits, timezone, hours) {
196	    return "{" +
197	      '"name":' + JSON.stringify(name) +
198	      ',"capacity":' + capacityDigits +
199	      ',"timezone":' + JSON.stringify(timezone) +
200	      ',"weeklyHours":' + JSON.stringify(hours) +
201	      "}";
202	  }
203	
204	  // parseVenuesJSON 解析场地列表，但保留 capacity 数字的十进制原文：
205	  // JSON.parse 会把数字存成 float64，超过 2^53 的容量会被舍入成相邻整数。
206	  // 这里逐字符扫描 JSON（正确处理字符串内的转义引号），仅当 "capacity"
207	  // 作为对象键出现时，把其后数字的原文包成字符串，页面拿到的就是服务端
208	  // 逐位发出的完整十进制数字（服务端只输出普通整数，不会出现科学计数法）。
209	  // 名称等其它字段一律原样复制，绝不改写；线上传输的 JSON 中 capacity
210	  // 仍是数字，接口格式不变。
211	  function parseVenuesJSON(text) {
212	    var out = "", i = 0, n = text.length;
213	    while (i < n) {
214	      if (text[i] !== '"') {
215	        out += text[i];
216	        i++;
217	        continue;
218	      }
219	      // 读取完整字符串，跳过转义字符，使名称中出现的 \"capacity\":1
220	      // 之类文本不会被误认为对象键。
221	      var tokenStart = i, j = i + 1;
222	      while (j < n) {
223	        if (text[j] === "\\") { j += 2; continue; }
224	        if (text[j] === '"') { j++; break; }
225	        j++;
226	      }
227	      var token = text.slice(tokenStart, j);
228	      // 对象键后面（允许空白）必然是 ':'；字符串值后面只能是 ',' 或 '}'。
229	      var k = j;
230	      while (k < n && /\s/.test(text[k])) k++;
231	      if (text[k] !== ":" || JSON.parse(token) !== "capacity") {
232	        out += token;
233	        i = j;
234	        continue;
235	      }
236	      // 复制到 ':' 之后（含中间空白），再把数字原文引用为字符串。
237	      out += token + text.slice(j, k + 1);
238	      var p = k + 1;
239	      while (p < n && /\s/.test(text[p])) { out += text[p]; p++; }
240	      var numStart = p;
241	      while (p < n && /[-+0-9eE.]/.test(text[p])) p++;
242	      out += JSON.stringify(text.slice(numStart, p));
243	      i = p;
244	    }
245	    return JSON.parse(out);
246	  }
247	
248	  function renderVenues(venues) {
249	    if (!venues.length) {
250	      listBox.innerHTML = '<div class="empty">还没有场地记录。</div>';
251	      return;
252	    }
253	    var sortedHours = function (hours) {
254	      return hours.slice().sort(function (a, b) {
255	        if (a.weekday !== b.weekday) return a.weekday - b.weekday;
256	        return toMinutes(a.start) - toMinutes(b.start);
257	      });
258	    };
259	    listBox.innerHTML = venues.map(function (venue) {
260	      var hoursHTML;
261	      if (!venue.weeklyHours || !venue.weeklyHours.length) {
262	        hoursHTML = '<p class="venue-meta">开放时段：暂未开放</p>';
263	      } else {
264	        var items = sortedHours(venue.weeklyHours).map(function (h) {
265	          var overnight = toMinutes(h.end) < toMinutes(h.start);
266	          var endLabel = overnight ? '<span class="next-day">次日 ' + escapeHTML(h.end) + "</span>" : escapeHTML(h.end);
267	          return "<li>" + WEEKDAYS[h.weekday] + " " + escapeHTML(h.start) + " – " + endLabel + "</li>";
268	        }).join("");
269	        hoursHTML = '<ul class="hours">' + items + "</ul>";
270	      }
271	      return '<article class="venue-card">' +
272	        "<h3>" + escapeHTML(venue.name) + "</h3>" +
273	        '<p class="venue-meta">容量：' + escapeHTML(venue.capacity) + " 人</p>" +
274	        '<p class="venue-meta">时区：' + escapeHTML(venue.timezone) + "</p>" +
275	        hoursHTML +
276	        "</article>";
277	    }).join("");
278	  }
279	
280	  // 列表读取可能交错：页面打开时的读取尚未结束，保存成功又会触发一次新
281	  // 的读取。以读取的“发起顺序”为准：每次发起都取一个更大的序号，只有
282	  // 最近一次发起的读取允许在成功或失败时改写列表区域；更早发出的读取
283	  // 无论随后成功（哪怕返回的是空数组）还是失败（HTTP 错误、无效 JSON、
284	  // 连接失败），结果一律丢弃，不能覆盖最近一次读取的列表或错误提示。
285	  var listSequence = 0;
286	
287	  function loadVenues() {
288	    var thisLoad = ++listSequence;
289	    return fetch("/api/venues", { headers: { Accept: "application/json" } })
290	      .then(function (res) {
291	        if (!res.ok) throw new Error("读取场地列表失败（HTTP " + res.status + "）");
292	        return res.text();
293	      })
294	      .then(function (text) {
295	        var data;
296	        try {
297	          data = parseVenuesJSON(text);
298	        } catch (e) {
299	          throw new Error("读取场地列表失败：响应不是有效的 JSON");
300	        }
301	        // 又有更新的读取发出后，本次（旧）读取的成功结果不再写入列表，
302	        // 包括空数组：空提示只能来自最近一次读取，不能借旧结果清掉列表。
303	        if (thisLoad !== listSequence) return;
304	        renderVenues(data.venues || []);
305	      })
306	      .catch(function (err) {
307	        // 旧读取随后失败（HTTP 错误/无效 JSON/连接失败）时，也不能把最近
308	        // 一次读取已经显示的列表或错误提示换成这次旧失败。
309	        if (thisLoad !== listSequence) return;
310	        listBox.innerHTML = '<div class="empty">' + escapeHTML(err.message) + "</div>";
311	      });
312	  }
313	
314	  form.addEventListener("submit", function (event) {
315	    event.preventDefault();
316	    clearError();
317	
318	    var name = document.getElementById("name").value.trim();
319	    var capacityDigits = canonicalDigits(document.getElementById("capacity").value);
320	    var timezone = document.getElementById("timezone").value.trim();
321	
322	    if (!name) { showError("保存失败：名称不能为空。"); return; }
323	    if (capacityDigits === null) { showError("保存失败：容量必须是正整数。"); return; }
324	    if (!timezone) { showError("保存失败：请填写所在时区。"); return; }
325	
326	    var collected = collectHours();
327	    if (collected.error) { showError("保存失败：" + collected.error); return; }
328	
329	    // 本次提交保存的始终是点击保存那一刻的内容：名称、容量、时区与时段在
330	    // 上方已经取定，请求体直接使用这些快照值。随后无论用户怎么改，都不会
331	    // 影响已经发出的请求，也不能把后来的输入当成已保存数据。
332	    var thisSubmit = ++submitSequence;
333	    formDirty = false;
334	
335	    // 失败时不重置表单，保留全部填写内容。
336	    fetch("/api/venues", {
337	      method: "POST",
338	      headers: { "Content-Type": "application/json", Accept: "application/json" },
339	      // 容量按输入的十进制原文作为 JSON 数字发送，不经过 Number/parseInt：
340	      // 是否超出服务端范围由服务端按这个准确整数判断，绝不先舍入再提交。
341	      body: buildVenueRequestBody(name, capacityDigits, timezone, collected.hours)
342	    }).then(function (res) {
343	      return res.json().catch(function () { return {}; }).then(function (body) {
344	        return { ok: res.ok, status: res.status, body: body };
345	      });
346	    }).then(function (result) {
347	      var isLatest = thisSubmit === submitSequence;
348	      if (!result.ok) {
349	        // 已有更新的一次保存发出时，旧响应不再覆盖界面状态；最新一次保存
350	        // 的成败由它自己的响应负责展示。
351	        if (!isLatest) return;
352	        var reason = result.body && result.body.error ? result.body.error : "HTTP " + result.status;
353	        showError("保存失败：" + reason);
354	        return;
355	      }
356	      // 只有最新一次保存成功、且请求在途期间表单一次都没被动过，才沿用既
357	      // 有行为：清空字段、移除时段行、消除错误提示。只要用户在等待期间改
358	      // 过任何字段或时段行（哪怕又改回提交时的值），或之后又发起了新的保
359	      // 存，就完整保留当前整份表单及其顺序；后来填成空值或非法内容也同样
360	      // 保留，不影响这次合法提交的成功展示。
361	      if (isLatest && !formDirty) {
362	        form.reset();
363	        hoursRows.innerHTML = "";
364	        clearError();
365	      }
366	      // 无论新旧，成功保存的记录都来自服务端数据，刷新列表让该次提交的
367	      // 记录出现，不混入用户尚未提交的改动。
368	      return loadVenues();
369	    }).catch(function (err) {
370	      // 已有更新的保存发出时，忽略旧请求的连接失败提示。
371	      if (thisSubmit !== submitSequence) return;
372	      // 连接失败：展示本次保存的失败原因并保留当前填写内容，不恢复旧值。
373	      // loadVenues 内部已自行处理列表渲染失败，不会走到这里。
374	      showError("保存失败：无法连接服务（" + err.message + "），请稍后重试。");
375	    });
376	  });
377	
378	  loadVenues();
379	})();
380	</script>
381	</html>
