13	)
14	
15	// 首页容量准确性端到端回归：
16	//
17	// 服务端的精确整数校验已由 HTTP 层测试覆盖；这里补上“用户在首页表单填写
18	// → 浏览器提交 → 服务端保存 → 首页列表显示”这一段的保障。测试启动真实
19	// HTTP 服务（httptest）与本机无头 Chrome，由 testdata/homepage_browser_test.mjs
20	// 通过 Chrome DevTools Protocol 驱动真实首页，逐字节检查请求/响应中的
21	// capacity，并验证列表显示与失败时的表单保留行为。
22	//
23	// 脚本不依赖任何 npm 包（Node ≥22 的全局 WebSocket 即可），在缺少 node 或
24	// Chrome 的环境中跳过，保证其余测试照常运行。可用 CHROME_BIN 指定浏览器。
25	
26	type browserCheckResult struct {
27		HarnessError string `json:"harnessError"`
28		Browser      string `json:"browser"`
29		Checks       []struct {
30			Scenario string `json:"scenario"`
31			Name     string `json:"name"`
32			Pass     bool   `json:"pass"`
33			Detail   string `json:"detail"`
34		} `json:"checks"`
35	}
36	
37	func findExecutable(t *testing.T, names []string, candidates []string) string {
38		t.Helper()
39		for _, name := range names {
40			if p, err := exec.LookPath(name); err == nil {
41				return p
42			}
43		}
44		for _, p := range candidates {
45			if info, err := os.Stat(p); err == nil && !info.IsDir() {
46				if abs, err := filepath.Abs(p); err == nil {
47					return abs
48				}
49			}
50		}
51		return ""
52	}
53	
54	func TestHomepageCapacityBrowserE2E(t *testing.T) {
55		nodeBin := findExecutable(t, []string{"node"}, []string{
56			"/opt/gsb-production/bin/node",
57			"/usr/local/bin/node",
58			"/usr/bin/node",
59		})
60		if nodeBin == "" {
61			t.Skip("未找到 node，跳过首页浏览器端到端测试")
62		}
63		chromeBin := findExecutable(t,
64			[]string{"google-chrome", "google-chrome-stable", "chromium", "chromium-browser"},
65			[]string{
66				os.Getenv("CHROME_BIN"),
67				"/usr/bin/google-chrome",
68				"/usr/bin/google-chrome-stable",
69				"/usr/bin/chromium",
70				"/usr/bin/chromium-browser",
71				"/usr/local/bin/google-chrome",
72			})
73		if chromeBin == "" {
74			t.Skip("未找到 Chrome/Chromium（可用 CHROME_BIN 指定），跳过首页浏览器端到端测试")
75		}
76	
77		// 与线上相同的处理链：临时数据目录 + 真实 HTTP 服务。
78		_, handler := newTestServer(t)
79		srv := httptest.NewServer(handler)
80		defer srv.Close()
81	
82		harness := filepath.Join("testdata", "homepage_browser_test.mjs")
83		ctx, cancel := context.WithTimeout(context.Background(), 150*time.Second)
84		defer cancel()
85		cmd := exec.CommandContext(ctx, nodeBin, harness, srv.URL, chromeBin)
86		var stdout, stderr strings.Builder
87		cmd.Stdout = &stdout
88		cmd.Stderr = &stderr
89		if err := cmd.Run(); err != nil {
90			t.Fatalf("运行首页浏览器脚本失败: %v\nstderr:\n%s\nstdout:\n%s", err, stderr.String(), stdout.String())
91		}
92	
93		// 脚本只在最后一行输出 JSON 结果。
94		var result browserCheckResult
95		lines := strings.Split(strings.TrimSpace(stdout.String()), "\n")
96		var report string
97		for i := len(lines) - 1; i >= 0; i-- {
98			line := strings.TrimSpace(lines[i])
99			if line == "" {
100				continue
101			}
102			var probe browserCheckResult
103			if err := json.Unmarshal([]byte(line), &probe); err == nil {
104				result = probe
105				report = line
106				break
107			}
108		}
109		if report == "" {
110			t.Fatalf("浏览器脚本没有输出 JSON 结果\nstderr:\n%s\nstdout:\n%s", stderr.String(), stdout.String())
111		}
112		if result.HarnessError != "" {
113			t.Fatalf("浏览器脚本基础设施故障: %s\nstderr:\n%s", result.HarnessError, stderr.String())
114		}
115		if len(result.Checks) == 0 {
116			t.Fatalf("浏览器脚本没有产出任何检查项: %s", report)
117		}
118		t.Logf("浏览器：%s，共 %d 项页面行为检查", result.Browser, len(result.Checks))
119	
120		failures := 0
121		for _, c := range result.Checks {
122			if !c.Pass {
123				failures++
124			}
125			c := c
126			t.Run(subtestName(c.Scenario, c.Name), func(t *testing.T) {
127				if !c.Pass {
128					t.Errorf("%s / %s 未通过%s", c.Scenario, c.Name, detailSuffix(c.Detail))
129				}
130			})
131		}
132		if failures > 0 {
133			t.Fatalf("首页容量端到端回归共有 %d 项失败", failures)
134		}
135	}
136	
137	// subtestName 把场景与检查名拼成稳定的子测试名（去掉会影响层级显示的斜杠）。
138	func subtestName(scenario, name string) string {
139		safe := func(s string) string {
140			var b strings.Builder
141			for _, r := range s {
142				if r == '/' || r == '\\' {
143					r = ' '
144				}
145				b.WriteRune(r)
146			}
147			return strings.TrimSpace(b.String())
148		}
149		return safe(scenario) + " · " + safe(name)
150	}
151	
152	func detailSuffix(detail string) string {
153		detail = strings.ReplaceAll(detail, "\n", " ")
154		if len(detail) > 600 {
155			detail = detail[:600] + "…"
156		}
157		if detail == "" {
158			return ""
159		}
160		return "：" + detail
161	}
