376	async function main() {
377	  const chrome = await launchChrome();
378	  /** @type {CDP} */
379	  let cdp;
380	  try {
381	    const list = await (await fetch(`http://127.0.0.1:${chrome.port}/json/list`)).json();
382	    const page = list.find((t) => t.type === "page") || list[0];
383	    cdp = new CDP(page.webSocketDebuggerUrl);
384	    await cdp.connect();
385	    await cdp.send("Page.enable");
386	    await cdp.send("Runtime.enable");
387	    await cdp.send("Network.enable");
388	
389	    const pageErrors = [];
390	    cdp.on((method, params) => {
391	      if (method === "Runtime.exceptionThrown") {
392	        pageErrors.push(params.exceptionDetails.text +
393	          (params.exceptionDetails.exception ? " " + params.exceptionDetails.exception.description : ""));
394	      }
395	    });
396	
397	    const net = createNetworkLog(cdp);
398	
399	    const navigate = async () => {
400	      await cdp.send("Page.navigate", { url: baseURL + "/" });
401	      // 等待初始列表渲染完成（“正在加载…”消失）。
402	      await poll(async () => {
403	        const text = await cdp.eval(`document.getElementById("venue-list").textContent`);
404	        return text && text.indexOf("正在加载") === -1;
405	      }, { timeout: 8000, label: "初始列表加载" });
406	      await sleep(100);
407	    };
408	    await navigate();
409	
410	    const state = () => cdp.eval(`(${PAGE_STATE})()`);
411	    const fill = (data) => cdp.evalFn(PAGE_FILL, data);
412	    const fillPartial = (data) => cdp.evalFn(PAGE_FILL_PARTIAL, data);
413	    const removeAllHours = () => cdp.eval(`(${PAGE_REMOVE_ALL_HOURS})()`);
414	    const changeLastHourStart = (value) => cdp.evalFn(PAGE_CHANGE_LAST_START, value);
415	    const submit = () => cdp.eval(`(${PAGE_SUBMIT})()`);
416	    const findCard = (cards, name) => cards.find((c) => c.name === name) || null;
417	    const capacityOnCard = (card) => {
418	      const m = card.text.match(/容量：(\S+)\s*人/);
419	      return m ? m[1] : null;
420	    };
421	
422	    // 提交后等待一个新的 POST /api/venues 响应落地。
423	    const submitAndWaitPost = async () => {
424	      const before = net.snapshot().filter((r) => r.method === "POST").length;
425	      await submit();
426	      const posts = await poll(async () => {
427	        const got = net.venuePosts(before);
428	        return got.length ? got : null;
429	      }, { timeout: 8000, label: "POST /api/venues" });
430	      // 再等页面渲染（成功后还会触发一次列表 GET）。
431	      await sleep(250);
432	      return posts[0];
433	    };
434	
435	    // 从 JSON 文本里取出 capacity 的原始写法（不解析成 Number）。
436	    const rawCapacityToken = (raw) => {
437	      const m = raw.match(/"capacity"\s*:\s*([^,}\s]+)/);
438	      return m ? m[1] : null;
439	    };
440	
441	    // ---------- 场景 1：2^53+1 大整数完整往返 ----------
442	    {
443	      const S = "大整数容量 9007199254740993";
444	      const exact = "9007199254740993";
445	      const neighbor = "9007199254740992";
446	      try {
447	        await fill({ name: "超大容量馆", capacity: exact, timezone: "Asia/Shanghai", hours: [] });
448	        const post = await submitAndWaitPost();
449	        const raw = await net.postDataOf(post);
450	
451	        check(S, "请求已发出且为 JSON", !!raw && raw.trim().startsWith("{"), raw);
452	        const token = raw ? rawCapacityToken(raw) : null;
