        check(S, "请求 capacity 是未加引号的 JSON 数字", token !== null && token[0] !== '"',
          `token=${token}`);
        check(S, "请求未被舍入成相邻整数 9007199254740992", raw.indexOf(neighbor) === -1, raw);
        check(S, "服务端返回 201", post.status === 201, `status=${post.status}`);

